<div class="card MainCard"><div class="card-header d-flex justify-content-between align-items-center"><div><h5 class="fw-bold mb-1">Lista de evaluación</h5><span class="text-muted small">Captura las calificaciones del grupo · Escala <?= HGlobal($TextoRangoCalificacion) ?></span></div><div class="badge bg-dark px-3 py-2 rounded-pill"><?= (int)$TotalAlumnos ?> Alumnos</div></div><div class="card-body p-0"><form method="POST" id="FormCalificaciones" data-calificacion-min="<?= HGlobal((string)$ConfigCalificacion['Minima']) ?>" data-calificacion-max="<?= HGlobal((string)$ConfigCalificacion['Maxima']) ?>" data-calificacion-aprobatoria="<?= HGlobal((string)$ConfigCalificacion['Aprobatoria']) ?>"><input type="hidden" name="AsignacionId" value="<?= (int)$AsignacionId ?>"><input type="hidden" name="PeriodoId" value="<?= (int)$PeriodoId ?>"><div class="SgcePeriodoBox mb-3"><label for="PeriodoIdSelect"><i class="fa-solid fa-calendar-days"></i> Periodo de evaluación</label><select id="PeriodoIdSelect" class="form-select" data-asignacion-id="<?= (int)$AsignacionId ?>"><?php foreach ($PeriodosDisponibles as $Periodo): ?><option value="<?= (int)$Periodo['Id'] ?>" <?= (int)$Periodo['Id'] === (int)$PeriodoId ? 'selected' : '' ?>><?= HGlobal($Periodo['CicloNombre'] . ' - ' . $Periodo['Nombre']) ?></option><?php endforeach; ?></select></div><?= CampoCsrf() ?><input type="hidden" name="GuardarNotes"><div class="table-responsive"><table class="table align-middle mb-0 SgceTable SgceGradesMobileTable"><thead><tr><th>Alumno</th><th class="text-center SgceCalificacionValorCol">Calificación</th></tr></thead><tbody><?php if(empty($Alumnos)): ?><tr><td colspan="2"><?= SgceComponenteTablaVacia('No hay alumnos registrados') ?></td></tr><?php else: foreach($Alumnos as $Al): ?><tr class="AlumnoRow"><td><div class="d-flex align-items-center gap-3"><div class="AlumnoAvatar AlumnoAvatarEmoji"><span class="SgceAlumnoEmoji" aria-hidden="true">🧑‍🎓</span></div><div><div class="AlumnoNombre"><?= HGlobal($Al['NombreCompleto']) ?></div></div></div></td><td><input type="number" name="Notas[<?= (int)$Al['AlumnoId'] ?>]" class="form-control text-center InputNota" step="<?= !empty($ConfigCalificacion['Decimales']) ? '0.01' : '1' ?>" min="<?= HGlobal((string)$ConfigCalificacion['Minima']) ?>" max="<?= HGlobal((string)$ConfigCalificacion['Maxima']) ?>" placeholder="-" data-original="<?= HGlobal($Al['Calificacion'] !== null ? $Al['Calificacion'] : '') ?>" value="<?= HGlobal($Al['Calificacion'] !== null ? $Al['Calificacion'] : '') ?>"></td></tr><?php endforeach; endif; ?></tbody></table></div><?php if(!empty($Alumnos)): ?><div class="SgceStickyActions border-top d-flex justify-content-end"><button type="submit" id="BtnGuardarCalificacionesVerdeMetalico" class="btn BtnGuardar BtnGuardarCalificacionesVerdeMetalico text-white"><span class="SgceColorIcon me-2" aria-hidden="true">💾</span><span>Guardar calificaciones</span></button></div><?php endif; ?></form></div></div>
